import{_ as t,l,o as e,c as n,v as i,p as s,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"二次剩余","description":"","frontmatter":{"title":"二次剩余","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quadratic-residue.md","filePath":"cs/quadratic-residue.md","lastUpdated":1789023840000}'),h={name:"cs/quadratic-residue.md"};function u(b,a,m,q,_,f){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="二次剩余" tabindex="-1">二次剩余 <a class="header-anchor" href="#二次剩余" aria-label="Permalink to &quot;二次剩余&quot;">​</a></h1><div class="epigraph"><p>模 $p$ 的平方剩余由勒让德符号判定，欧拉准则 $a^{(p-1)/2}\\equiv\\pm 1$；模 $n=pq$ 的二次剩余判定与分解一样硬，这是若干比特承诺的老家。</p><footer>—— 据 Gauss；Ireland and Rosen 整理</footer></div><p>上一课<a href="/cs/generator-discrete-log">离散对数</a> 是指数。缺口是<strong>平方</strong>：哪些 \\(a\\) 有 \\(x^2\\equiv a\\pmod p\\)。勒让德 \\((\\frac{a}{p})\\)，二次互反律用来算。模合数 \\(n\\) 的 Jacobi 可多项式计算，却不回答是否真平方——Goldwasser–Micali 等协议吃这一缝。本课不写协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\mathbb{F}_p^\\times\\) 循环，平方恰一半元素。欧拉：\\(a^{(p-1)/2}\\equiv(\\frac{a}{p})\\pmod p\\)。Tonelli–Shanks 在 \\(p\\bmod 4\\) 等条件下开方。模 \\(n=pq\\)：若知 \\(p,q\\) 可 CRT 开方；不知则 QR 判定等价某些困难假设。Jacobi \\((\\frac{a}{n})\\) 把勒让德乘起来，可多项式算，但对 QR 有假阳性。</p><p>不要把「平方根模 \\(n\\)」写成 OWF 的唯一例子：它与分解等价（Rabin）。点名。</p><h3 id="jacobi-不是勒让德" tabindex="-1">Jacobi 不是勒让德 <a class="header-anchor" href="#jacobi-不是勒让德" aria-label="Permalink to &quot;Jacobi 不是勒让德&quot;">​</a></h3><p>\\((\\frac{a}{n})=1\\) 仍可能非剩余。写程序时用 Jacobi 当「是否平方」会错。</p><p><span class="marginnote">Gauss 二次互反。Ireland–Rosen 第 5–6 章。Cipolla、Tonelli–Shanks 开方。本课要判别与合数缝隙，不证互反律。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在模 \\(11\\) 列出平方表，核对欧拉准则。指出互反律把 \\((\\frac{p}{q})\\) 换成 \\((\\frac{q}{p})\\) 带符号，便于手算。对照 Miller–Rabin：那里用 \\(a^{(n-1)/2}\\) 一类当见证，下一课。</p>',11)),(e(),s(c,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22a%20mod%20p%22%5D%20--%3E%20EUL%5B%22a%5E%7B(p-1)%2F2%7D%22%5D%0A%20%20EUL%20--%3E%20LEG%5B%22%E5%8B%92%E8%AE%A9%E5%BE%B7%20%C2%B11%20%2F%200%22%5D%0A%20%20N%5B%22a%20mod%20pq%22%5D%20--%3E%20JAC%5B%22Jacobi%20%E6%98%93%E7%AE%97%22%5D%0A%20%20JAC%20--%3E%20GAP%5B%22%E2%89%A0%20%E7%9C%9F%20QR%20%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>QR 给「比特藏在剩余/非剩余」的经典承诺。后课格密码不再依赖 QR。素性测试用相关的幂，但见证选择不同。本课把平方这一层钉在 DLP 与素性之间。</p><p>二次互反：\\((\\frac{p}{q})(\\frac{q}{p})=(-1)^{(p-1)(q-1)/4}\\)（奇素数）。手算勒让德靠它。Tonelli–Shanks 在素数域开方多项式。Rabin 加密：平方模 \\(n\\)，解密开方，与分解等价。GM 承诺用模 \\(n\\) 的 QR 藏一比特，本课不写协议。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证二次互反，不引入高次剩余。不写 Goldwasser–Micali 加密。后课默认：模 \\(p\\) 的 QR 易判；模 \\(pq\\) 的真 QR 难。下一课 Miller–Rabin。</p><p>模 \\(p\\) 的 QR 易判、可开方；模 \\(pq\\) 的真 QR 与分解同级难，Jacobi 却好算——缝隙是承诺方案的老家。欧拉准则的平方链形状，下一课变成 Miller–Rabin 见证。</p><p>上一课留下的缺口在本课收口；「二次剩余」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模 \\(p\\)：一半平方；欧拉准则给勒让德。</li><li>模 \\(pq\\)：Jacobi 易、真 QR 难；开方与分解等价。</li><li>Jacobi \\(=1\\) 不是剩余的充要条件。</li><li>出处：Gauss；Ireland and Rosen。</li></ul>',9))])}const A=t(h,[["render",u]]);export{R as __pageData,A as default};
